N,M=map(int,input().split())
S=[input() for i in range(N)]
T=[input() for j in range(M)]
ans_lst=[0]*N
for j in range(M):
    if T[j] in S:
        ans_lst[S.index(T[j])]+=1
    else:
        I=[]
        for i in range(N):
            if len(S[i])==len(T[j]) and sum(s!=t for s,t in zip(S[i],T[j]))==1:
                I.append(i)
        if len(I)==1:
            ans_lst[I[0]]+=1
print(*ans_lst,sep="\n")
